INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine EULA dasselbe wie ein Kaufvertrag?', 2, '[{"text": "No", "correct": true, "because": "License vs. ownership"}, {"text": "Yes", "correct": false, "because": "Different purposes"}]'),
('00000000-0000-0000-0000-000000000000', 'What is the primary purpose of an EULA?', 3, '[{"text": "Define software usage rights", "correct": true, "because": "Regulates user permissions"}, {"text": "Sell hardware", "correct": false, "because": "Software-focused"}, {"text": "Secure networks", "correct": false, "because": "Not security-related"}]'),
('00000000-0000-0000-0000-000000000000', 'Which elements are typically included in an EULA?', 5, '[{"text": "License scope", "correct": true, "because": "Usage rights"}, {"text": "Restrictions", "correct": true, "because": "Limitations defined"}, {"text": "Paper specifications", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) An EULA grants usage rights to the user. b) It transfers software ownership.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "No ownership transfer"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I ignore in an EULA?', 4, '[{"text": "Usage restrictions", "correct": false, "because": "Key component"}, {"text": "License terms", "correct": false, "because": "Core element"}, {"text": "Font size", "correct": true, "because": "Irrelevant to function"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if an EULA is legally binding?', 2, '[{"text": "Yes", "correct": true, "because": "Contractual agreement"}, {"text": "No", "correct": false, "because": "Legally enforceable"}]'),
('00000000-0000-0000-0000-000000000000', 'Who typically provides an EULA?', 3, '[{"text": "Software vendor", "correct": true, "because": "Creator defines terms"}, {"text": "Hardware manufacturer", "correct": false, "because": "Software-specific"}, {"text": "Printer company", "correct": false, "because": "Not relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'What benefits does an EULA provide?', 5, '[{"text": "Protects intellectual property", "correct": true, "because": "Vendor rights"}, {"text": "Clarifies usage rules", "correct": true, "because": "User guidance"}, {"text": "Increases hardware speed", "correct": false, "because": "Not technical"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard: a) An EULA limits software copying. b) It’s only for free software. Is that true?', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Applies to all software"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What don’t I need for an EULA?', 4, '[{"text": "License terms", "correct": false, "because": "Core requirement"}, {"text": "Usage conditions", "correct": false, "because": "Essential"}, {"text": "Physical signature", "correct": true, "because": "Digital acceptance"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Is an EULA optional for software?', 2, '[{"text": "No", "correct": true, "because": "Standard practice"}, {"text": "Yes", "correct": false, "because": "Typically required"}]'),
('00000000-0000-0000-0000-000000000000', 'Which software typically includes an EULA?', 4, '[{"text": "Commercial software", "correct": true, "because": "Licensed products"}, {"text": "Open-source software", "correct": true, "because": "Often with terms"}, {"text": "Paper manuals", "correct": false, "because": "Not software"}]'),
('00000000-0000-0000-0000-000000000000', 'I’ve heard that an EULA is only for large companies. Is that true?', 2, '[{"text": "No", "correct": true, "because": "All software sizes"}, {"text": "Yes", "correct": false, "because": "Widely used"}]'),
('00000000-0000-0000-0000-000000000000', 'What do I prioritize in an EULA?', 3, '[{"text": "Clarity of terms", "correct": true, "because": "User understanding"}, {"text": "Color scheme", "correct": false, "because": "Irrelevant"}, {"text": "Speed of acceptance", "correct": false, "because": "Comprehension key"}]'),
('00000000-0000-0000-0000-000000000000', 'Are these statements correct? a) An EULA can restrict software modifications. b) It’s a hardware warranty.', 3, '[{"text": "Only a) is correct", "correct": true, "because": "Not hardware-related"}, {"text": "Both are correct", "correct": false, "because": "b) is false"}, {"text": "Only b) is correct", "correct": false, "because": "a) is true"}, {"text": "Both are false", "correct": false, "because": "a) is true"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s typically restricted in an EULA?', 5, '[{"text": "Copying", "correct": true, "because": "IP protection"}, {"text": "Reverse engineering", "correct": true, "because": "Code security"}, {"text": "Paper usage", "correct": false, "because": "Not relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s unimportant in an EULA?', 3, '[{"text": "License duration", "correct": false, "because": "Key term"}, {"text": "Usage rights", "correct": false, "because": "Core element"}, {"text": "Print format", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'How was it again? Can an EULA be enforced without acceptance?', 3, '[{"text": "No", "correct": true, "because": "User consent required"}, {"text": "Yes", "correct": false, "because": "Acceptance needed"}]'),
('00000000-0000-0000-0000-000000000000', 'Can you recall if an EULA applies to free software?', 2, '[{"text": "Yes", "correct": true, "because": "Usage terms apply"}, {"text": "No", "correct": false, "because": "Not exclusive to paid"}]'),
('00000000-0000-0000-0000-000000000000', 'What’s central to an EULA?', 4, '[{"text": "Defining usage rights", "correct": true, "because": "Core purpose"}, {"text": "Hardware specs", "correct": false, "because": "Not relevant"}, {"text": "Paper records", "correct": false, "because": "Irrelevant"}]');
